      "keystrokes": "cat > Makefile << 'MAKEFILE'
# Trinity Compress Makefile targets

.PHONY: optimize-prompts optimize-undo optimize-aggressive optimize-help

# Run compression in balanced mode (default)
optimize-prompts:
	@echo "Running Trinity Compress (balanced mode)..."
	@bash scripts/trinity-compress.sh balanced

# Run compression in aggressive mode
optimize-aggressive:
	@echo "Running Trinity Compress (aggressive mode)..."
	@bash scripts/trinity-compress.sh aggressive

# Undo compression - restore from backups
optimize-undo:
	@echo "Restoring from backups..."
	@bash scripts/trinity-compress.sh balanced undo

# Show help
optimize-help:
	@echo "Trinity Compress Makefile targets:"
	@echo "  make optimize-prompts     - Compress prompts in balanced mode"
	@echo "  make optimize-aggressive  - Compress prompts in aggressive mode"
	@echo "  make optimize-undo        - Restore from backups"
	@echo "  make optimize-help        - Show this help"
MAKEFILE
